import{c as r,Q as n,j as a,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Measuring Harness-Induced Belief Divergence in Multi-Step LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.04528","title":"Measuring Harness-Induced Belief Divergence in Multi-Step LLM Agents","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2607.04528,"authors":["Haiwen Yi","Xinyuan Song"],"pdf_path":"pdfs/2607.04528.pdf","published_date":"2026-07-05T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-07-05-measuring-harness-induced-belief-divergence-2607-04528.md","filePath":"research/papers/2026-07-05-measuring-harness-induced-belief-divergence-2607-04528.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-07-05-measuring-harness-induced-belief-divergence-2607-04528.md"};function t(o,e,c,l,d,g){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="measuring-harness-induced-belief-divergence-in-multi-step-llm-agents" tabindex="-1">Measuring Harness-Induced Belief Divergence in Multi-Step LLM Agents <a class="header-anchor" href="#measuring-harness-induced-belief-divergence-in-multi-step-llm-agents" aria-label="Permalink to &quot;Measuring Harness-Induced Belief Divergence in Multi-Step LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Haiwen Yi, Xinyuan Song <strong>Published</strong>: July 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2607.04528" target="_blank" rel="noreferrer">https://arxiv.org/abs/2607.04528</a><strong>arXiv ID</strong>: 2607.04528 <strong>Categories</strong>: Computer Science - Artificial Intelligence (cs.AI) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2607.04528" target="_blank" rel="noreferrer">research/papers/pdfs/2607.04528.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This research investigates how evaluation frameworks affect agent decision-making in language models. The authors observe that even when task specifications and underlying models remain constant, the testing infrastructure—including action restrictions, repair handling, and evidence logging—can meaningfully alter an agent&#39;s reasoning patterns. To measure this phenomenon, they developed a diagnostic tool that captures agent beliefs across nine dimensions including progress, risk, recoverability, constraints, failure mode, uncertainty, future success, repair cost, and next action under different testing setups. Their analysis on coding benchmarks reveals that blocking certain actions, limiting repair information, restricting verification checks, and filtering evidence often preserve task completion while shifting the underlying reasoning processes. They propose BIWM, a standardization protocol that reconciles observations across different evaluation frameworks by logging hidden branches, documenting repair history, recording verification outcomes, and executing risky actions in isolated simulation.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>揭示一個容易被忽略的變因：即使任務規格與底層模型完全相同，<strong>評測 harness 本身</strong>（動作限制、修復處理、證據記錄方式）就會顯著改變 agent 的推理內容，即使最終任務完成率不變。</li><li>設計九維度信念探測工具（progress、risk、recoverability、constraints、failure mode、uncertainty、future success、repair cost、next action），量化不同 harness 設定下 agent「內在信念」的偏移程度。</li><li>在程式碼 benchmark 上發現：封鎖特定動作、限制修復資訊、限縮驗證檢查、過濾證據——這些 harness 層面的選擇常常「任務完成率不變、但推理過程已經改變」，是一種隱形的評測污染。</li><li>提出 BIWM 標準化協議（記錄隱藏分支、修復歷史、驗證結果，並在隔離模擬中執行風險動作）調和跨 harness 的觀測差異。</li><li><strong>Workspace 關聯</strong>：呼應本庫既有 Harness-Bench（2605.27922，同批次收錄）「agent capability 應以 model-harness 組態層級回報」的立場，並進一步指出即使任務完成率一致，harness 差異仍可能污染「推理過程」本身——對 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的「verdict 非證據，需機械重驗」提供更細緻的失真來源分類。</li></ul>',8)])])}const p=r(s,[["render",t]]);export{h as __pageData,p as default};
